// One-off demo recording against the deployed Azure DataQ instance. Reuses the
// e2e-live captured OIDC session (frontend/e2e-live/.auth/session.json) rather
// than logging in itself. Walks through the features highlighted on the new
// marketing landing page: Dashboard overview, Connections, Suites (Data
// Quality Monitoring), a check run's Results (pass-rate trend), Orchestration
// tracking (pipeline runs tab), Automated Alerting (per-suite notifications
// panel), and Profile (RBAC / workspace settings).
import fs from 'node:fs';
import path from 'node:path';
import { chromium } from '@playwright/test';

const BASE_URL = process.env.E2E_LIVE_BASE_URL;
if (!BASE_URL) {
  throw new Error('set E2E_LIVE_BASE_URL to the deployed frontend URL');
}
const SESSION_FILE = path.resolve('e2e-live', '.auth', 'session.json');
const OUT_DIR = process.env.DEMO_OUT_DIR || path.resolve('demo-video');
fs.mkdirSync(OUT_DIR, { recursive: true });

const pause = (ms) => new Promise((r) => setTimeout(r, ms));

// Waits for any Ant Design skeleton blocks / "Loading …" text to clear, then
// a short settle — the live app's first paint is a skeleton, not the data.
async function settle(page, { dwell = 3200 } = {}) {
  await page
    .waitForFunction(
      () => !document.querySelector('.ant-skeleton') && !/Loading [a-z]+…?\.\.\./.test(document.body.innerText),
      { timeout: 20_000 },
    )
    .catch(() => {});
  await pause(dwell);
}

async function main() {
  const session = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf8'));
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    recordVideo: { dir: OUT_DIR, size: { width: 1440, height: 900 } },
  });
  await context.addInitScript((stored) => {
    for (const [key, value] of Object.entries(stored)) {
      window.sessionStorage.setItem(key, value);
    }
  }, session);

  const page = await context.newPage();

  // 1. Dashboard — overall data-integrity / pass-rate KPIs.
  await page.goto(`${BASE_URL}/dashboard`);
  await page.getByRole('heading', { name: 'Dashboard', level: 3 }).waitFor({ timeout: 30_000 });
  await settle(page, { dwell: 4000 });

  // 2. Connections — centralized data-source management.
  await page.goto(`${BASE_URL}/connections`);
  await page.getByRole('heading', { name: 'Connections', level: 3 }).waitFor({ timeout: 15_000 });
  await settle(page, { dwell: 3600 });

  // 3. Suites — reusable validation groups (Data Quality Monitoring + Suites cards).
  await page.goto(`${BASE_URL}/suites`);
  await page.getByRole('heading', { name: 'Suites', level: 3 }).waitFor({ timeout: 15_000 });
  await settle(page, { dwell: 2600 });
  const firstSuiteCard = page.locator('.ant-card').first();
  if (await firstSuiteCard.count()) {
    await firstSuiteCard.click();
    await page.waitForURL(/\/suites\/[0-9a-f-]+$/, { timeout: 15_000 }).catch(() => {});
    await settle(page, { dwell: 3200 });
    // Automated Alerting — the per-suite notifications panel lives on this page.
    const notifHeading = page.getByText(/notification/i).first();
    if (await notifHeading.count()) {
      await notifHeading.scrollIntoViewIfNeeded().catch(() => {});
      await pause(3200);
    }
  }

  // 4. Results — runs table + a run detail drill-down (pass-rate / check results).
  await page.goto(`${BASE_URL}/results`);
  await page.getByRole('heading', { name: 'Results', level: 3 }).waitFor({ timeout: 15_000 });
  await settle(page, { dwell: 2400 });
  const firstRun = page.locator('tr.ant-table-row').first();
  if (await firstRun.count()) {
    await firstRun.click();
    await page.waitForURL(/\/results\/[0-9a-f-]+$/, { timeout: 15_000 }).catch(() => {});
    await settle(page, { dwell: 3600 });
    await page.goBack();
    await page.getByRole('heading', { name: 'Results', level: 3 }).waitFor({ timeout: 15_000 });
  }

  // 5. Orchestration Tracking — the Pipeline runs tab on the same page.
  const pipelineTab = page.getByRole('tab', { name: /pipeline runs/i });
  if (await pipelineTab.count()) {
    await pipelineTab.click();
    await settle(page, { dwell: 3600 });
  }

  // 6. Profile — RBAC / workspace settings.
  await page.goto(`${BASE_URL}/profile`);
  await page.getByRole('heading', { name: 'Profile', level: 3 }).waitFor({ timeout: 15_000 }).catch(() => {});
  await settle(page, { dwell: 3600 });

  await context.close();
  await browser.close();

  const files = fs.readdirSync(OUT_DIR).filter((f) => f.endsWith('.webm'));
  console.log('DEMO_VIDEO_FILES', JSON.stringify(files.map((f) => path.join(OUT_DIR, f))));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

