// One-off demo recording against the deployed Azure DataQ instance. Shows the
// real sign-in flow (DataQ's own login screen, then the Azure AD redirect)
// unauthenticated, then swaps in the e2e-live captured OIDC session
// (frontend/e2e-live/.auth/session.json) to continue authenticated — avoids a
// second live MFA round-trip mid-recording. Walks through every feature card
// on the marketing landing page, plus the connection/suite/check creation
// flows. Each named beat's start offset + fixed dwell is written to
// marks.json so a narration track can be built and synced against it after.
import fs from 'node:fs';
import path from 'node:path';
import { chromium } from '@playwright/test';

const BASE_URL = process.env.E2E_LIVE_BASE_URL;
if (!BASE_URL) {
  throw new Error('set E2E_LIVE_BASE_URL to the deployed frontend URL');
}
const SESSION_FILE = path.resolve('e2e-live', '.auth', 'session.json');
const OUT_DIR = process.env.DEMO_OUT_DIR || path.resolve('demo-video');
fs.mkdirSync(OUT_DIR, { recursive: true });

const pause = (ms) => new Promise((r) => setTimeout(r, ms));

async function main() {
  const session = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf8'));
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    recordVideo: { dir: OUT_DIR, size: { width: 1440, height: 900 } },
  });
  const page = await context.newPage();
  const t0 = Date.now();
  const marks = [];

  // Waits for skeletons/"Loading …" text to clear (best-effort), records a
  // named beat at the current offset, then holds for `dwell` ms so the beat
  // has a known, fixed on-screen duration to narrate against.
  async function beat(label, dwell) {
    await page
      .waitForFunction(
        () => !document.querySelector('.ant-skeleton') && !/Loading [a-z]+…?\.\.\./.test(document.body.innerText),
        { timeout: 20_000 },
      )
      .catch(() => {});
    marks.push({ label, t: Date.now() - t0, dur: dwell });
    await pause(dwell);
  }

  try {
    // 0a. DataQ's own sign-in screen — unauthenticated, no session injected yet.
    await page.goto(BASE_URL);
    await page.getByRole('heading', { name: 'Sign in to DataQ' }).waitFor({ timeout: 20_000 });
    await beat('signin', 5000);

    // 0b. Kick off the real Azure AD redirect — proves it's genuine SSO, not a
    // mocked screen. Don't complete it (needs live MFA).
    await page.getByRole('button', { name: 'Sign in' }).click();
    await page.waitForURL(/login\.microsoftonline\.com/, { timeout: 20_000 }).catch(() => {});
    marks.push({ label: 'azuread', t: Date.now() - t0, dur: 4200 });
    await pause(4200);

    // Register the captured session for the NEXT navigation only.
    await page.addInitScript((stored) => {
      for (const [key, value] of Object.entries(stored)) {
        window.sessionStorage.setItem(key, value);
      }
    }, session);

    // 1. Dashboard.
    await page.goto(`${BASE_URL}/dashboard`);
    await page.getByRole('heading', { name: 'Dashboard', level: 3 }).waitFor({ timeout: 30_000 });
    await beat('dashboard', 5200);

    // 2. Connections.
    await page.goto(`${BASE_URL}/connections`);
    await page.getByRole('heading', { name: 'Connections', level: 3 }).waitFor({ timeout: 15_000 });
    await beat('connections', 4400);

    // 2b. New connection — type picker + (once a type is chosen) the form.
    await page.goto(`${BASE_URL}/connections/new`);
    await page.getByRole('heading', { name: 'New connection' }).waitFor({ timeout: 15_000 });
    await beat('connection-new', 4200);
    const snowflakeType = page.getByText('Snowflake', { exact: true }).first();
    if (await snowflakeType.count()) {
      await snowflakeType.click();
      await pause(300);
      marks.push({ label: 'connection-form', t: Date.now() - t0, dur: 3800 });
      await pause(3800);
    }

    // 3. Suites.
    await page.goto(`${BASE_URL}/suites`);
    await page.getByRole('heading', { name: 'Suites', level: 3 }).waitFor({ timeout: 15_000 });
    await beat('suites', 3600);

    // 3b. New suite.
    await page.goto(`${BASE_URL}/suites/new`);
    await page.getByRole('heading', { name: 'New suite' }).waitFor({ timeout: 15_000 });
    await beat('suite-new', 4200);

    // 3c. Suite detail — checks, triggers, schedules, notifications.
    await page.goto(`${BASE_URL}/suites`);
    await page.getByRole('heading', { name: 'Suites', level: 3 }).waitFor({ timeout: 15_000 });
    let suiteId = null;
    const firstSuiteCard = page.locator('.ant-card').first();
    if (await firstSuiteCard.count()) {
      await firstSuiteCard.click();
      await page.waitForURL(/\/suites\/[0-9a-f-]+$/, { timeout: 15_000 }).catch(() => {});
      await beat('suite-detail', 3600);
      suiteId = page.url().match(/\/suites\/([0-9a-f-]+)$/)?.[1] ?? null;
      const notifHeading = page.getByText(/notification/i).first();
      if (await notifHeading.count()) {
        await notifHeading.scrollIntoViewIfNeeded().catch(() => {});
        marks.push({ label: 'notifications', t: Date.now() - t0, dur: 4200 });
        await pause(4200);
      }
    }

    // 3d. New check — catalog-driven picker.
    if (suiteId) {
      await page.goto(`${BASE_URL}/suites/${suiteId}/checks/new`);
      await page.getByRole('heading', { name: 'New check' }).waitFor({ timeout: 15_000 });
      await beat('check-new', 4200);
    }

    // 4. Results — a run with per-check failures, expand one for its metric
    // trend + (where the check is row-predicate) the redacted sample rows.
    await page.goto(`${BASE_URL}/results`);
    await page.getByRole('heading', { name: 'Results', level: 3 }).waitFor({ timeout: 15_000 });
    await beat('results', 3200);

    const RUN_CANDIDATES = ['Iceberg — Purchase Orders', 'Unity Catalog — Feedback', 'Flat File — Logistics Tracking'];
    let expandedLabel = null;
    for (const suiteName of RUN_CANDIDATES) {
      const runRow = page.locator('tr.ant-table-row', { hasText: suiteName }).first();
      if (!(await runRow.count())) continue;
      await runRow.click();
      await page.waitForURL(/\/results\/[0-9a-f-]+$/, { timeout: 15_000 }).catch(() => {});
      await pause(1200);

      const rows = page.locator('tr.ant-table-row');
      const rowCount = await rows.count();
      for (let i = 0; i < Math.min(rowCount, 6); i++) {
        const row = rows.nth(i);
        const icon = row.locator('.ant-table-row-expand-icon');
        if (!(await icon.count())) continue;
        await icon.click();
        await pause(900);
        const bodyText = await page.locator('body').innerText();
        if (/redact/i.test(bodyText)) {
          expandedLabel = 'run-detail-redacted';
          break;
        }
        await icon.click(); // collapse, try the next row
      }
      if (expandedLabel) break;
      // No redaction on this run — still worth showing the metric trend once.
      if (!expandedLabel && rowCount > 0) {
        const row = rows.nth(0);
        const icon = row.locator('.ant-table-row-expand-icon');
        if (await icon.count()) {
          await icon.click();
          expandedLabel = 'run-detail-trend';
        }
      }
      if (expandedLabel) break;
      await page.goto(`${BASE_URL}/results`);
      await page.getByRole('heading', { name: 'Results', level: 3 }).waitFor({ timeout: 15_000 });
    }
    marks.push({ label: expandedLabel || 'run-detail-trend', t: Date.now() - t0, dur: 5200 });
    await pause(5200);

    await page.goto(`${BASE_URL}/results`);
    await page.getByRole('heading', { name: 'Results', level: 3 }).waitFor({ timeout: 15_000 }).catch(() => {});

    // 5. Orchestration Tracking — Pipeline runs tab.
    const pipelineTab = page.getByRole('tab', { name: /pipeline runs/i });
    if (await pipelineTab.count()) {
      await pipelineTab.click();
      await beat('pipeline', 4200);
    }

    // 6. Profile — RBAC / workspace settings.
    await page.goto(`${BASE_URL}/profile`);
    await page.getByRole('heading', { name: 'Profile', level: 3 }).waitFor({ timeout: 15_000 }).catch(() => {});
    await beat('profile', 4200);
  } finally {
    await context.close();
    await browser.close();
  }

  fs.writeFileSync(path.join(OUT_DIR, 'marks.json'), JSON.stringify(marks, null, 2));
  const files = fs.readdirSync(OUT_DIR).filter((f) => f.endsWith('.webm'));
  console.log('DEMO_VIDEO_FILES', JSON.stringify(files.map((f) => path.join(OUT_DIR, f))));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

