const rowCount = await rows.count();
const order = [];
for (const status of ['fail', 'warn']) {
  for (let i = 0; i < rowCount; i++) {
    const text = (await rows.nth(i).innerText().catch(() => '')).toLowerCase();
    if (text.includes(status) && !order.includes(i)) order.push(i);
  }
}
