// Records a short intro clip from the local marketing landing page (no live
// Azure dependency) — Hero, then a scroll through the Features section.
import fs from 'node:fs';
import path from 'node:path';
import { chromium } from '@playwright/test';

const URL = process.env.INTRO_URL || 'http://localhost:8940/';
const OUT_DIR = process.env.DEMO_OUT_DIR || path.resolve('intro-video');
fs.mkdirSync(OUT_DIR, { recursive: true });
const pause = (ms) => new Promise((r) => setTimeout(r, ms));

async function main() {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    recordVideo: { dir: OUT_DIR, size: { width: 1440, height: 900 } },
  });
  const page = await context.newPage();
  try {
    await page.goto(URL);
    await page.getByText('Trust your data,').waitFor({ timeout: 15_000 });
    await pause(4500); // hero

    await page.evaluate(() => window.scrollTo({ top: 850, behavior: 'instant' }));
    await pause(4500); // features bento grid

    await page.evaluate(() => window.scrollTo({ top: 1650, behavior: 'instant' }));
    await pause(3500); // connections/suites/results/profile cards
  } finally {
    await context.close();
    await browser.close();
  }
  const files = fs.readdirSync(OUT_DIR).filter((f) => f.endsWith('.webm'));
  console.log('INTRO_VIDEO_FILES', JSON.stringify(files.map((f) => path.join(OUT_DIR, f))));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

// One-off demo recording against the deployed Azure DataQ instance. Shows the
// real sign-in flow (DataQ's own login screen, then the Azure AD redirect)
// unauthenticated, then swaps in the e2e-live captured OIDC session
// (frontend/e2e-live/.auth/session.json) to continue authenticated — avoids a
// second live MFA round-trip mid-recording. Walks through every feature card
// on the marketing landing page, plus the connection/suite/check creation
// flows. Each named beat's start offset + fixed dwell is written to
// marks.json so a narration track can be built and synced against it after.
//
// Kept deliberately light on live API calls (no retry loops hammering the
// same endpoint) — the deployed app rate-limits per token/IP (ADR 0035), and
// a hammered session can flash the sign-in screen when a call gets throttled.
import fs from 'node:fs';
import path from 'node:path';
import { chromium } from '@playwright/test';

const BASE_URL = process.env.E2E_LIVE_BASE_URL;
if (!BASE_URL) {
  throw new Error('set E2E_LIVE_BASE_URL to the deployed frontend URL');
}
const SESSION_FILE = path.resolve('e2e-live', '.auth', 'session.json');
const OUT_DIR = process.env.DEMO_OUT_DIR || path.resolve('demo-video');
fs.mkdirSync(OUT_DIR, { recursive: true });

const pause = (ms) => new Promise((r) => setTimeout(r, ms));
const SIGNIN_HEADING = 'Sign in to DataQ';

async function main() {
  const session = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf8'));
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    recordVideo: { dir: OUT_DIR, size: { width: 1440, height: 900 } },
  });
  const page = await context.newPage();
  const t0 = Date.now();
  const marks = [];

  // Navigates to an authenticated route and waits for its heading. If a
  // transient auth hiccup flashes the sign-in screen instead (a throttled or
  // slow /me call), reload once rather than recording the wrong screen.
  async function gotoAuthed(urlPath, headingName, level = 3) {
    for (let attempt = 0; attempt < 2; attempt++) {
      await page.goto(`${BASE_URL}${urlPath}`);
      const heading = page.getByRole('heading', { name: headingName, level });
      const signin = page.getByRole('heading', { name: SIGNIN_HEADING });
      const result = await Promise.race([
        heading.waitFor({ timeout: 20_000 }).then(() => 'ok'),
        signin.waitFor({ timeout: 20_000 }).then(() => 'signin'),
      ]).catch(() => 'timeout');
      if (result === 'ok') return true;
      await pause(1500);
    }
    return false;
  }

  // Waits for skeletons/"Loading …" text to clear (best-effort), records a
  // named beat at the current offset, then holds for `dwell` ms so the beat
  // has a known, fixed on-screen duration to narrate against.
  async function beat(label, dwell) {
    await page
      .waitForFunction(
        () => !document.querySelector('.ant-skeleton') && !/Loading [a-z]+…?\.\.\./.test(document.body.innerText),
        { timeout: 20_000 },
      )
      .catch(() => {});
    marks.push({ label, t: Date.now() - t0, dur: dwell });
    await pause(dwell);
  }

  try {
    // 0a. DataQ's own sign-in screen — unauthenticated, no session injected yet.
    await page.goto(BASE_URL);
    await page.getByRole('heading', { name: SIGNIN_HEADING }).waitFor({ timeout: 20_000 });
    marks.push({ label: 'signin', t: Date.now() - t0, dur: 5000 });
    await pause(5000);

    // 0b. Kick off the real Azure AD redirect — proves it's genuine SSO, not a
    // mocked screen. Don't complete it (needs live MFA).
    await page.getByRole('button', { name: 'Sign in' }).click();
    await page.waitForURL(/login\.microsoftonline\.com/, { timeout: 20_000 }).catch(() => {});
    marks.push({ label: 'azuread', t: Date.now() - t0, dur: 4200 });
    await pause(4200);

    // Register the captured session for every navigation from here on.
    await page.addInitScript((stored) => {
      for (const [key, value] of Object.entries(stored)) {
        window.sessionStorage.setItem(key, value);
      }
    }, session);

    // 1. Dashboard.
    if (!(await gotoAuthed('/dashboard', 'Dashboard'))) throw new Error('dashboard did not load authenticated');
    await beat('dashboard', 5200);

    // 2. Connections.
    await gotoAuthed('/connections', 'Connections');
    await beat('connections', 4400);

    // 2b. New connection — type picker + (once a type is chosen) the form.
    await gotoAuthed('/connections/new', 'New connection');
    await beat('connection-new', 4200);
    const snowflakeType = page.getByText('Snowflake', { exact: true }).first();
    if (await snowflakeType.count()) {
      await snowflakeType.click();
      await pause(300);
      marks.push({ label: 'connection-form', t: Date.now() - t0, dur: 3800 });
      await pause(3800);
    }

    // 3. Suites.
    await gotoAuthed('/suites', 'Suites');
    await beat('suites', 3600);

    // 3b. New suite.
    await gotoAuthed('/suites/new', 'New suite');
    await beat('suite-new', 4200);

    // 3c. Suite detail — checks, triggers, schedules, notifications.
    await gotoAuthed('/suites', 'Suites');
    let suiteId = null;
    const firstSuiteCard = page.locator('.ant-card').first();
    if (await firstSuiteCard.count()) {
      await firstSuiteCard.click();
      await page.waitForURL(/\/suites\/[0-9a-f-]+$/, { timeout: 15_000 }).catch(() => {});
      await beat('suite-detail', 3200);
      suiteId = page.url().match(/\/suites\/([0-9a-f-]+)$/)?.[1] ?? null;
      // The suite page's sub-panels (checks/triggers/schedules/notifications)
      // each fetch independently — wait for ALL their "Loading …" text to
      // clear, not just the page shell, before scrolling to notifications.
      await page
        .waitForFunction(() => !/Loading [a-z]+…?\.\.\./.test(document.body.innerText), { timeout: 15_000 })
        .catch(() => {});
      const notifHeading = page.getByText(/^Notifications$/).first();
      if (await notifHeading.count()) {
        await notifHeading.scrollIntoViewIfNeeded().catch(() => {});
        marks.push({ label: 'notifications', t: Date.now() - t0, dur: 4200 });
        await pause(4200);
      }
    }

    // 3d. New check — catalog-driven picker.
    if (suiteId) {
      await gotoAuthed(`/suites/${suiteId}/checks/new`, 'New check');
      await beat('check-new', 4200);
    }

    // 4. Results — the "Iceberg — Purchase Orders" run has a row-predicate
    // check ("po_line within band") that fails with a real, redacted
    // failing-row sample plus a metric trend — expand it directly rather
    // than searching, to keep API calls to a minimum.
    await gotoAuthed('/results', 'Results');
    await beat('results', 2600);

    const cell = page.getByRole('cell', { name: 'Iceberg — Purchase Orders' }).first();
    let expandedLabel = null;
    if (await cell.count()) {
      await cell.click();
      const navigated = await page
        .waitForURL(/\/results\/[0-9a-f-]+$/, { timeout: 15_000 })
        .then(() => true)
        .catch(() => false);
      if (navigated) {
        const rows = page.locator('tr.ant-table-row');
        let rowCount = 0;
        for (let attempt = 0; attempt < 15; attempt++) {
          rowCount = await rows.count();
          if (rowCount > 0) break;
          await pause(400);
        }
        // Search from the last row backward — "po_line within band" (the
        // check with the redacted sample) is the last row in this suite.
        for (let i = rowCount - 1; i >= 0 && !expandedLabel; i--) {
          const icon = rows.nth(i).locator('.ant-table-row-expand-icon');
          if (!(await icon.count())) continue;
          await icon.click();
          await pause(700);
          const bodyText = await page.locator('body').innerText();
          if (/redact/i.test(bodyText)) {
            expandedLabel = 'run-detail-redacted';
          } else if (!/no sample rows captured/i.test(bodyText) && /failing rows|trend/i.test(bodyText)) {
            expandedLabel = 'run-detail-trend';
          } else {
            await icon.click(); // collapse, try the previous row
          }
        }
      }
    }
    marks.push({ label: expandedLabel || 'run-detail-trend', t: Date.now() - t0, dur: 5200 });
    await pause(5200);

    // 5. Orchestration Tracking — Pipeline runs tab.
    await gotoAuthed('/results', 'Results');
    const pipelineTab = page.getByRole('tab', { name: /pipeline runs/i });
    if (await pipelineTab.count()) {
      await pipelineTab.click();
      await beat('pipeline', 4200);
    }

    // 6. Profile — RBAC / workspace settings.
    await gotoAuthed('/profile', 'Profile');
    await beat('profile', 4200);
  } finally {
    await context.close();
    await browser.close();
  }

  fs.writeFileSync(path.join(OUT_DIR, 'marks.json'), JSON.stringify(marks, null, 2));
  const files = fs.readdirSync(OUT_DIR).filter((f) => f.endsWith('.webm'));
  console.log('DEMO_VIDEO_FILES', JSON.stringify(files.map((f) => path.join(OUT_DIR, f))));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

