// DataQ marketing — top navigation bar. Brand left, links center,
// sign-in + Get Started right. Composes the design system Button.
const DQnav = window.DataQDesignSystem_317fec;

function MarketingNav() {
  const { Button } = DQnav;
  const GITHUB_URL = 'https://github.com/TheurgicDuke771/DataQ';
  const DOCS_URL = 'https://theurgicduke771.github.io/DataQ/docs/';
  const links = [
    { label: 'Features', href: '#features' },
    { label: 'Docs', href: DOCS_URL },
    { label: 'GitHub', href: GITHUB_URL },
  ];
  return (
    <header style={{
      position: 'sticky', top: 0, zIndex: 50,
      display: 'flex', alignItems: 'center', gap: 24,
      height: 64, padding: '0 32px',
      background: 'rgba(255,255,255,0.85)', backdropFilter: 'blur(8px)',
      borderBottom: '1px solid var(--border)',
    }}>
      <div style={{ flex: 1, display: 'flex', alignItems: 'center', gap: 32 }}>
        <a href="/" style={{ display: 'inline-flex', alignItems: 'center', gap: 10, textDecoration: 'none' }}>
          <img src={window.__resources.mark} width="28" height="28" alt="" />
          <span style={{ fontFamily: 'var(--font-sans)', fontWeight: 700, fontSize: 18, color: 'var(--ink)', letterSpacing: '-0.01em' }}>DataQ</span>
        </a>
        <nav style={{ display: 'flex', gap: 24 }}>
          {links.map((l) => (
            <a key={l.label} href={l.href} style={{ fontFamily: 'var(--font-sans)', fontSize: 14, fontWeight: 500, color: 'var(--text-body)', textDecoration: 'none' }}>{l.label}</a>
          ))}
        </nav>
      </div>
      <a href={GITHUB_URL} style={{ fontFamily: 'var(--font-sans)', fontSize: 14, fontWeight: 500, color: 'var(--text-body)', textDecoration: 'none' }}>Sign in</a>
      <a href={GITHUB_URL} style={{ textDecoration: 'none' }}><Button variant="primary" size="md">Get Started</Button></a>
    </header>
  );
}

Object.assign(window, { MarketingNav });

// DataQ marketing — hero. Eyebrow + headline + subcopy + dual CTA on
// the left; a floating product preview (real DS components) on the right.
const DQhero = window.DataQDesignSystem_317fec;

function HeroPreview() {
  const { Card, MetricCard, StatusBadge, ProgressBar } = DQhero;
  const I = window.Icon;
  return (
    <div style={{ position: 'relative' }}>
      {/* soft indigo glow */}
      <div style={{ position: 'absolute', inset: -24, background: 'radial-gradient(60% 60% at 70% 30%, rgba(79,70,229,0.16), transparent)', filter: 'blur(8px)' }} />
      <Card padding={18} style={{ position: 'relative', boxShadow: 'var(--shadow-float)', borderColor: 'var(--border)' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 14 }}>
          <span style={{ fontSize: 14, fontWeight: 600, color: 'var(--text-primary)' }}>Results Overview</span>
          <StatusBadge status="succeeded" variant="soft" />
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, marginBottom: 12 }}>
          <MetricCard label="Pass Rate" value="94.2%" delta="+1.2%" trend="up" progress={94.2} style={{ padding: 14 }} />
          <MetricCard label="Anomalies" value="128" delta="-14%" trend="down" footnote="last 7 days" style={{ padding: 14 }} />
        </div>
        <Card padding={14} style={{ background: 'var(--bg-subtle)', border: '1px solid var(--border)' }}>
          {[
            { n: 'Daily Revenue Audit', s: 'pass', v: 100 },
            { n: 'Customer Ingestion', s: 'fail', v: 62 },
            { n: 'ML Feature Store', s: 'warn', v: 88 },
          ].map((r) => (
            <div key={r.n} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '6px 0' }}>
              <span style={{ flex: 1, fontSize: 12, color: 'var(--text-body)' }}>{r.n}</span>
              <div style={{ width: 80 }}><ProgressBar value={r.v} tone={r.s === 'pass' ? 'pass' : r.s === 'fail' ? 'fail' : 'warning'} /></div>
              <StatusBadge status={r.s} variant="soft" style={{ width: 64, justifyContent: 'center' }} />
            </div>
          ))}
        </Card>
      </Card>
    </div>
  );
}

function Hero() {
  const { Button } = DQhero;
  const I = window.Icon;
  const GITHUB_URL = 'https://github.com/TheurgicDuke771/DataQ';
  const DOCS_URL = 'https://theurgicduke771.github.io/DataQ/docs/';
  return (
    <section style={{ background: 'var(--bg-app)', borderBottom: '1px solid var(--border)' }}>
      <div style={{ maxWidth: 1200, margin: '0 auto', padding: '80px 32px 96px', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 56, alignItems: 'center' }}>
        <div>
          <span style={{ display: 'inline-flex', alignItems: 'center', gap: 7, height: 28, padding: '0 12px', borderRadius: 'var(--radius-full)', background: 'var(--indigo-50)', color: 'var(--indigo-700)', border: '1px solid var(--indigo-100)', fontSize: 12, fontWeight: 600, letterSpacing: '.04em', textTransform: 'uppercase' }}>
            <I.zap size={13} /> Next-gen monitoring
          </span>
          <h1 style={{ margin: '20px 0 0', fontFamily: 'var(--font-sans)', fontSize: 52, lineHeight: 1.08, fontWeight: 700, letterSpacing: '-0.025em', color: 'var(--ink)' }}>
            Trust your data,<br />powered by DataQ
          </h1>
          <p style={{ margin: '20px 0 0', fontSize: 18, lineHeight: 1.55, color: 'var(--text-secondary)', maxWidth: 480 }}>
            Comprehensive data quality monitoring, orchestration tracking, and automated alerting for modern data teams. Eliminate the &ldquo;Silent Expert&rdquo; bottleneck.
          </p>
          <div style={{ display: 'flex', gap: 12, marginTop: 32 }}>
            <a href={GITHUB_URL} style={{ textDecoration: 'none' }}><Button variant="primary" size="lg">Get Started</Button></a>
            <a href={DOCS_URL} style={{ textDecoration: 'none' }}><Button variant="secondary" size="lg">Read the Docs</Button></a>
          </div>
          <div style={{ marginTop: 28, fontSize: 13, color: 'var(--text-muted)' }}>
            Snowflake · Databricks Unity Catalog · Apache Iceberg · ADLS Gen2 · AWS S3 — monitored through Great Expectations.
          </div>
        </div>
        <HeroPreview />
      </div>
    </section>
  );
}

Object.assign(window, { Hero });

