          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <img src={window.__resources.mark} width="26" height="26" alt="" />
              <span style={{ fontWeight: 700, fontSize: 17, color: 'var(--ink)' }}>DataQ</span>
